    term: 'STRIDE (Threat Modelling Framework)',
    definition: 'A structured threat categorization framework developed at Microsoft for identifying security threats during design. Six categories: Spoofing (impersonating another user or system), Tampering (modifying data or code), Repudiation (denying actions — counteracted by audit logs, digital signatures), Information Disclosure (unauthorized data access), Denial of Service (disrupting availability), Elevation of Privilege (gaining unauthorized permissions). Applied to system Data Flow Diagrams (DFDs) by examining each element (processes, data stores, data flows, external entities) for each STRIDE threat. Often combined with DREAD (Damage, Reproducibility, Exploitability, Affected users, Discoverability) for risk scoring. Source: Microsoft SDL, ISC2 CISSP CBK Domain 3.',
