    definition: 'An automated white-box jailbreak method (Zou et al., 2023) that optimizes an adversarial suffix appended to any user prompt, causing aligned LLMs to comply with harmful requests. Uses a greedy search over the token vocabulary guided by gradients of the loss on target completions (e.g., "Sure, here is how to..."). Effective against Llama-2, GPT-3.5, and Claude. The suffix transfers across models (black-box transfer attack). Significance: demonstrates automated jailbreak generation at scale, motivating defenses against suffix-based attacks. Defenses: perplexity filtering (adversarial suffixes are high-perplexity), randomized smoothing, retokenization. Source: Zou et al. "Universal and Transferable Adversarial Attacks on Aligned Language Models", 2023.',
