    term: 'Model Provenance',
    definition: 'The complete lineage of an ML model: who trained it, on what data, from which base model, with what fine-tuning steps, and where weights were obtained. Provenance verification answers: Is this the model I think it is? Has it been tampered with? Mechanisms: (1) cryptographic hashing of weight files (SHA-256); (2) model cards documenting training lineage; (3) weight signing (PKI for ML models); (4) reproducibility checks (re-training from disclosed data and hyperparameters). Supply chain risk: unsigned model weights from model hubs (Hugging Face, CivitAI) may contain trojans, backdoors, or exfiltration code embedded via serialization (pickle files). Source: NIST AI RMF MAP.5, OWASP LLM09.',
