    term: 'Secure Aggregation (Federated Learning)',
    definition: 'A cryptographic protocol in federated learning that allows the server to compute the aggregate of client updates without observing any individual update. Typically implemented using homomorphic encryption (HE) or secret sharing: each client\'s gradient is encrypted or secret-shared such that only the sum is revealed to the server. Prevents the server from performing gradient inversion attacks against individual clients. Trade-off: significant computational overhead vs. gradient privacy. Production implementations: Google\'s Secure Aggregation Protocol (Bonawitz et al., 2017) uses masked gradients that cancel out when summed. Source: Bonawitz et al. "Practical Secure Aggregation for Privacy-Preserving Machine Learning", CCS 2017.',
