    definition: 'The use of automated scanning, prioritization, and remediation tools to manage the vulnerability lifecycle at scale. Pipeline: (1) continuous scanning (Nessus, Qualys, Trivy, OpenVAS); (2) asset enrichment (link CVE to asset criticality, network exposure, exploit availability); (3) risk-based prioritization (CVSS score + EPSS probability of exploitation + asset business value); (4) automated remediation (patch via Ansible/Chef, container rebuild, WAF virtual patch); (5) validation scan to confirm fix. AI augmentation: ML models predict exploitation likelihood (EPSS), generate remediation scripts, and identify patch-breaking dependencies. GASAE focus: orchestrating the full VMP loop via SOAR integration. Source: GIAC GASAE; NIST SP 800-40.',
