    term: 'Neural Cleanse',
    definition: 'A backdoor/Trojan model detection technique (Wang et al., IEEE S&P 2019). For each possible target class, Neural Cleanse solves an optimization problem: find the minimum perturbation (trigger) that causes any input to classify as that class. Anomalously small perturbations (compared to the distribution across all classes) indicate a backdoor trigger. The optimization is run on a held-out clean dataset. Can also reconstruct the approximate trigger for forensic analysis. Alternative detection approaches: STRIP (perturbation-based), MNTD (meta-network detection), activation clustering.',
