    term: 'Membership Inference Attack',
    definition: 'An attack that determines whether a specific data point was included in an ML model\'s training set. Exploits the generalization gap: overfitted models show higher confidence (lower loss) on training examples than unseen examples. The shadow model attack trains auxiliary models on similar data to calibrate a membership classifier. Practical impact: in medical/financial/legal datasets, inferring membership reveals sensitive relationships (e.g., "this patient was in the clinical trial training set"). Defenses: differential privacy, regularization to reduce overfitting, restricting API outputs to top-1 prediction without confidence scores. Source: Shokri et al. (IEEE S&P 2017).',
