    term: 'Adversarial Training (Robustness)',
    definition: 'A defense technique against adversarial examples that augments training with adversarially perturbed examples. The training objective is minimax: find the worst-case perturbation for each example within a norm bound, then train to classify it correctly. Projected Gradient Descent (PGD) adversarial training (Madry et al., 2018) is the gold standard. Trade-offs: (1) Computationally expensive — 10x+ training cost; (2) Standard accuracy/robustness trade-off — adversarially trained models typically have lower clean accuracy; (3) Certified robustness provides mathematical guarantees within the threat model (norm ball). Source: "Towards Deep Learning Models Resistant to Adversarial Attacks" (Madry et al., ICLR 2018).',
