    term: 'Gradient Inversion Attack',
    definition: 'An attack on federated learning that reconstructs private training data from shared gradient updates. Demonstrated by "Deep Leakage from Gradients" (Zhu et al., NeurIPS 2019): for small batches, optimizing a reconstruction candidate to produce matching gradients recovers training images/text with high fidelity. Healthcare relevance: patient records can be recovered from gradient updates shared in a hospital federated learning deployment. Defenses: (1) DP-SGD — per-sample gradient clipping + Gaussian noise injection; (2) Secure aggregation — cryptographic protocols prevent server from seeing individual gradients; (3) Large batch sizes — inversion becomes harder for batch size > 32. Source: Zhu et al. (NeurIPS 2019); Google Federated Learning research.',
