    term: 'Federated Learning Security',
    definition: 'Federated learning (FL) trains ML models across distributed nodes without centralizing raw data — each node trains locally and shares only gradients or model updates. Security threats specific to FL: (1) Gradient inversion — server recovers training data from gradients; (2) Byzantine attacks — malicious clients submit poisoned gradients; (3) Model poisoning — backdoor injection through gradient manipulation; (4) Free-rider attacks — clients receive global model without contributing updates. Defenses: DP-SGD, secure aggregation (SMPC), Byzantine-robust aggregation (Krum, FLTrust), anomaly detection on gradient updates. Source: McMahan et al. (2017); Google FL research.',
