    term: 'Feature Drift',
    definition: 'A change in the statistical distribution of input features between training time and deployment/serving time. Types: (1) Covariate shift — input feature distribution P(X) changes while the conditional P(Y|X) remains stable; (2) Concept drift — the relationship P(Y|X) changes (the underlying patterns the model learned become invalid); (3) Data quality drift — unexpected nulls, new categories, encoding changes. Detection methods: Jensen-Shannon divergence, Kullback-Leibler divergence, Population Stability Index (PSI > 0.2 = significant shift), Wasserstein distance, chi-squared tests for categorical features. Feature drift precedes performance degradation because it is observable without ground truth labels. Source: Google MLE; AWS SageMaker Model Monitor documentation.',
