    term: 'EEOC Four-Fifths Rule',
    definition: 'A practical guideline from the U.S. Equal Employment Opportunity Commission\'s Uniform Guidelines on Employee Selection Procedures (29 CFR Part 1607) for identifying adverse impact in selection procedures. Rule: if the selection rate for any race, sex, or ethnic group is less than 80% (four-fifths) of the highest selection rate, adverse impact is indicated. Applied to algorithmic hiring: if an ML model selects 40% of Group A but only 28% of Group B (28/40 = 70% < 80%), adverse impact is present requiring validation of job-relatedness. Note: the 4/5 rule is a practical guideline, not a legal bright line — statistical significance tests are also used. Source: EEOC Uniform Guidelines; CAISP Domain 2; "Fairness and Machine Learning" (Barocas, Hardt, Narayanan).',
