    definition: 'Architecture pattern that grounds LLM responses in retrieved documents rather than relying on parametric knowledge. Pipeline: (1) Ingestion — documents split into chunks, chunks embedded as vectors, stored in vector store (Azure AI Search, FAISS, etc.); (2) Retrieval — user query embedded, similarity search finds top-k relevant chunks; (3) Augmentation — chunks injected into LLM prompt as context; (4) Generation — LLM produces response grounded in retrieved context. Advantages over fine-tuning: knowledge updatable without retraining; sources citeable; hallucinations reduced. Key design choices: chunk size (200–500 tokens typical), overlap (10–20%), embedding model, retrieval type (vector/keyword/hybrid), reranking. RAG does not eliminate hallucination but significantly reduces it for factual queries. Source: Lewis et al. (2020), "Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks"; Microsoft AI-103.',
