    term: 'Chunk Overlap (RAG)',
    definition: 'Document chunking parameter specifying the number of tokens shared between adjacent chunks to prevent semantic context loss at chunk boundaries. When a document is split into chunks of size N, an overlap of O means chunk[i+1] starts O tokens before the end of chunk[i]. Typical values: 10–20% of chunk size (e.g., 50-token overlap for 500-token chunks). Trade-off: larger overlap → better boundary context preservation, more storage cost, potentially redundant retrieval; zero overlap → efficient storage, risks missing concepts that span boundaries. In Azure AI Search integrated vectorization: set via chunkingProperties.overlapLength. Related parameter: chunk size — smaller chunks (100–200 tokens) give more precise retrieval; larger chunks (500–1000 tokens) give more per-chunk context for the LLM. Source: learn.microsoft.com/azure/search/vector-search-integrated-vectorization.',
