    definition: 'Process of partitioning an audio stream by speaker identity — determining "who spoke when." Output: timeline of speaker turns with labels (Speaker 1, Speaker 2, etc.) and word-level timestamps. Approaches: (1) Spectral clustering — extract speaker embeddings (x-vectors, d-vectors) per segment, cluster to find distinct speakers; (2) End-to-end neural diarization (EEND) — joint segmentation and speaker assignment; (3) Target-speaker tracking — when reference audio is available, identify the known speaker. Azure AI Speech implementation: available in batch transcription and real-time transcription; returns diarized utterances with speaker IDs. Limitations: overlapping speech (two speakers simultaneously) is still challenging; number of speakers can be specified or auto-detected. Distinct from Speaker Recognition (verification/identification against enrolled profiles). Source: learn.microsoft.com/azure/ai-services/speech-service/get-started-stt-diarization.',
