    term: 'Foundation Model',
    definition: 'Large neural network trained on broad, diverse data at scale using self-supervised learning, which can be adapted to many downstream tasks. Term coined by Stanford CRFM (2021). Key properties: (1) Scale — billions to trillions of parameters; trained on terabytes of text, images, code; (2) Self-supervised pretraining — no human-labeled data required (next-token prediction, masked token prediction, contrastive learning); (3) Emergent capabilities — zero-shot, few-shot reasoning, instruction following emerge at sufficient scale (Wei et al., 2022); (4) Transfer — one model adapts to many tasks via prompting or fine-tuning; (5) Modalities — text (LLMs), vision (ViT), text+vision (GPT-4o, Gemini), audio, code. Examples: GPT-4, Claude, Llama 3, Mistral, Phi-3. Risks: amplify biases in pretraining data; opacity of emergent behaviors. Source: Bommasani et al. (2021), "On the Opportunities and Risks of Foundation Models."',
