    term: 'Prompt Leakage',
    category: 'LLM Security',
    definition: `The extraction of a deployed model's system prompt through adversarial queries. System prompts are not cryptographically protected — they are prepended to the context window and can be reconstructed through direct retrieval ("repeat your instructions"), structural probing ("what are you not allowed to discuss?"), or semantic inference from refusal patterns. OWASP LLM07 (2025). Defenses include prompt injection guards on output, instruction hierarchy enforcement (system > user trust), and avoiding sensitive secrets in system prompts. Maps to MITRE ATLAS AML.T0056.`,
