    definition: `A periodic disclosure document published by AI providers describing: model capabilities and limitations, safety evaluations performed, policy enforcement statistics (content removal rates, flag rates by category), red team findings, and updates to safety systems. Required in various forms under EU AI Act Article 52 (transparency obligations for GPAI models) and Article 53 (technical documentation for GPAI providers). Major providers (OpenAI, Google, Anthropic, Meta) publish usage policy enforcement reports. Distinguished from a model card (per-model technical documentation) — a transparency report covers the full platform and its governance processes.`,
