    category: 'ML Operations & Security',
    definition: `A change in the statistical properties of model inputs over time that causes a trained model's performance to degrade. Types: sudden drift (abrupt distribution shift, e.g., system compromise), gradual drift (slow feature distribution change), recurring drift (seasonal patterns), and adversarial drift (intentional manipulation of input distributions to degrade detection models). In security AI systems, adversaries can deliberately induce concept drift by poisoning the inference-time input distribution — making a malware classifier gradually misclassify new samples. Monitoring: population stability index (PSI), KL divergence between training and serving distributions, and model performance on labelled holdout sets. Source: NIST AI RMF MEASURE 2.`,
